import manifest from '../assets/img/manifest.json'

// URLs for every optimised image, keyed by file name. Generated by
// `npm run images`; see scripts/optimize-images.mjs.
const urls = import.meta.glob<string>('../assets/img/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
})

export type ImageName = keyof typeof manifest

export interface ResolvedImage {
  src: string
  srcSet: string
  width: number
  height: number
}

export const hasImage = (name: string): name is ImageName => name in manifest

export function resolveImage(name: ImageName): ResolvedImage {
  const entry = manifest[name]
  const variants = entry.variants.map((variant) => ({
    ...variant,
    url: urls[`../assets/img/${variant.file}`] ?? '',
  }))
  return {
    src: variants[0]?.url ?? '',
    srcSet: variants.map((variant) => `${variant.url} ${variant.width}w`).join(', '),
    width: entry.width,
    height: entry.height,
  }
}
